      let buf = new StringBuilder();
      this.encodeCompressedGtin(buf, AI013x0xDecoder.HEADER_SIZE);
      this.encodeCompressedWeight(buf, AI013x0xDecoder.HEADER_SIZE + AI01weightDecoder.GTIN_SIZE, AI013x0xDecoder.WEIGHT_SIZE);
